-- ENG-04: remove default API-role grants from the inventoried application-owned public objects.
-- DEV catalog inventory: 31 application tables, 4 application sequences, and 78 application routines.
-- Reapply explicit role grants captured in the local catalog baseline, except business-request direct
-- DML: the client only reads its own requests; creation is through business_request_submit().
-- Default grants for API roles are revoked for future public objects owned by postgres.
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public REVOKE ALL ON TABLES FROM PUBLIC, anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public REVOKE ALL ON SEQUENCES FROM PUBLIC, anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC, anon, authenticated, service_role;

